S=.00022186
Z=.0193

def uvworld(uv,practice=False):
    u,v=uv
    return np.array([-.1-(v+.5-512)*S, -(u+.5-512)*S-(.1856 if practice else 0),Z])

def stroke(uv,practice=False,name='stroke',speed=.003):
    points=np.array([uvworld(p,practice) for p in uv])
    goto(points[0]+[0,0,.012],q=Q,t=1.4,precise=True,name=name+'_approach')
    P=[]
    def segment(a,b,vel):
        N=max(1,math.ceil(np.linalg.norm(b-a)/vel/.05))
        for f in np.linspace(0,1,N+1)[1:]:P.append(np.r_[a*(1-f)+b*f,Q])
    segment(points[0]+[0,0,.012],points[0],.007)
    P.extend([np.r_[points[0],Q]]*6)
    for a,b in zip(points[:-1],points[1:]):
        segment(a,b,speed)
        P.extend([np.r_[b,Q]]*4)
    P.extend([np.r_[points[-1],Q]]*6)
    segment(points[-1],points[-1]+[0,0,.012],.008)
    P.extend([np.r_[points[-1]+[0,0,.012],Q]]*8)
    return run(P,name=name,cam='practice_cam' if practice else 'canvas_cam',precise=True)
PY"}));
